/*
 * Discover: recipes from the bundled library (data/library.js, generated by
 * tools/build_library.py from Bar Assistant's MIT recipe data), matched to this
 * bar's inventory. Library recipes are read-only until added to your drinks.
 */

let libraryRecipes = [];
let libraryErrors = [];

// Validate the library against the current inventory. Recipes that reference
// items you've since deleted are dropped rather than failing the whole library.
function loadLibrary() {
  const raw = window.BAR_LIBRARY;
  libraryErrors = [];
  if (!raw || !Array.isArray(raw.recipes)) { libraryRecipes = []; return; }
  const refsOk = r => r && Array.isArray(r.ingredients) && r.ingredients.every(i =>
    !i || ((!i.item || itemsById.has(i.item)) && (!Array.isArray(i.substitutes) || i.substitutes.every(s => itemsById.has(s)))));
  const res = validateCatalog({ schema: CATALOG_SCHEMA, items: catalog.items, recipes: raw.recipes.filter(refsOk) });
  if (!res.catalog) {
    libraryErrors = res.errors;
    libraryRecipes = [];
    console.warn("Recipe library ignored:", res.errors.slice(0, 5));
    return;
  }
  libraryRecipes = res.catalog.recipes;
}

const libraryRecipeById = id => libraryRecipes.find(r => r.id === id);

// Library drinks not already in your catalog (by id or name).
function discoverableRecipes() {
  const ids = new Set(catalog.recipes.map(r => r.id));
  const names = new Set(catalog.recipes.map(r => r.name.toLowerCase()));
  return libraryRecipes.filter(r => !ids.has(r.id) && !names.has(r.name.toLowerCase()));
}

function renderDiscover() {
  const all = discoverableRecipes();
  document.getElementById("discoverTabCount").textContent = all.length;
  const q = document.getElementById("discoverSearch").value.toLowerCase().trim();
  const mode = document.getElementById("discoverReady").value;
  const shown = all.filter(r =>
    (!q || [r.name, r.vibe, r.type, ...r.ingredients.map(ingredientLabel)].join(" ").toLowerCase().includes(q)) &&
    (mode !== "CAN" || canMakeNow(r)) &&
    (mode !== "ONE" || missingItems(r).length === 1));
  document.getElementById("discoverCount").textContent = `${shown.length} of ${all.length} library drinks`;
  document.getElementById("discoverGrid").innerHTML = shown.map(r => recipeTileHtml(r, { library: true })).join("") || `
    <div class="col-span-full glass-card rounded-2xl p-10 text-center text-sm text-gray-300">
      ${all.length ? "No library drinks match." : "You've added every library drink that fits your bar."}
    </div>`;
}

function addLibraryRecipe(id) {
  const r = libraryRecipeById(id);
  if (!r || recipeById(id)) return;
  const added = commitCatalog({ ...catalog, recipes: [...catalog.recipes, JSON.parse(JSON.stringify(r))] },
    `Added “${r.name}” to your drinks.`);
  if (added) openRecipeModal(id);
}

// "Source: imbibemagazine.com · via Bar Assistant (MIT)"
function sourceHtml(r) {
  if (!r.source) return "";
  let label = esc(r.source);
  if (/^https?:\/\//.test(r.source)) {
    let host = r.source;
    try { host = new URL(r.source).hostname.replace(/^www\./, ""); } catch (e) { /* keep the raw text */ }
    label = `<a href="${esc(r.source)}" target="_blank" rel="noopener" class="text-gold underline">${esc(host)}</a>`;
  }
  const viaLibrary = r.id.startsWith("ba-")
    ? ` · via <a href="https://github.com/bar-assistant/data" target="_blank" rel="noopener" class="underline">Bar Assistant</a> (MIT)`
    : "";
  return `<p class="text-[11px] text-gray-400">Source: ${label}${viaLibrary}</p>`;
}
